"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[50479],{42661:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>r,contentTitle:()=>i,default:()=>c,frontMatter:()=>o,metadata:()=>a,toc:()=>d});var n=h(31085),s=h(71184);const o={sidebar_position:1,slug:"/bible/Luke/Luke_1",title:"Luke 1",hide_table_of_contents:!0},i="Luke",a={id:"bible/Luke/Luke 1",title:"Luke 1",description:"Chapter 1",source:"@site/docs/bible/Luke/Luke 1.md",sourceDirName:"bible/Luke",slug:"/bible/Luke/Luke_1",permalink:"/docs/bible/Luke/Luke_1",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Luke/Luke 1.md",tags:[],version:"current",sidebarPosition:1,frontMatter:{sidebar_position:1,slug:"/bible/Luke/Luke_1",title:"Luke 1",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Luke",permalink:"/docs/bible/Luke/"},next:{title:"Luke 2",permalink:"/docs/bible/Luke/Luke_2"}},r={},d=[{value:"Chapter 1",id:"chapter-1",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h1,{id:"luke",children:"Luke"}),"\n",(0,n.jsx)(t.h2,{id:"chapter-1",children:"Chapter 1"}),"\n",(0,n.jsx)(t.p,{children:"The conception of John the Baptist, and of Christ.  The visitation and canticle of the Blessed Virgin.  The birth of the Baptist and the canticle of Zachary."}),"\n",(0,n.jsx)(h,{verse:1,children:"Forasmuch as many have taken in hand to set forth in order a narration of the things that have been accomplished among us,"}),"\n",(0,n.jsx)(h,{verse:2,children:"According as they have delivered them unto us, who from the beginning were eyewitnesses and ministers of the word:"}),"\n",(0,n.jsx)(h,{verse:3,children:"It seemed good to me also, having diligently attained to all things from the beginning, to write to thee in order, most excellent Theophilus,"}),"\n",(0,n.jsx)(h,{verse:4,children:"That thou mayest know the verity of those words in which thou hast been instructed."}),"\n",(0,n.jsx)(h,{verse:5,children:"There was in the days of Herod, the king of Judea, a certain priest named Zachary, of the course of Abia: and his wife was of the daughters of Aaron, and her name Elizabeth."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Of the course of Abia...that is, of the rank of Abia, which word in the Greek is commonly put for the employment of one day: but here for the functions of a whole week. For, by the appointment of David, 1 Par. 24., the descendants from Aaron were divided into twenty-four families, of which the eighth was Abia, from whom descended this Zachary, who at this time was in the week of his priestly functions."})}),"\n",(0,n.jsx)(h,{verse:6,children:"And they were both just before God, walking in all the commandments and justifications of the Lord without blame."}),"\n",(0,n.jsx)(h,{verse:7,children:"And they had no son, for that Elizabeth was barren: and they both were well advanced in years."}),"\n",(0,n.jsx)(h,{verse:8,children:"And it came to pass, when he executed the priestly function in the order of his course before God,"}),"\n",(0,n.jsx)(h,{verse:9,children:"According to the custom of the priestly office, it was his lot to offer incense, going into the temple of the Lord."}),"\n",(0,n.jsx)(h,{verse:10,children:"And all the multitude of the people was praying without, at the hour of incense."}),"\n",(0,n.jsx)(h,{verse:11,children:"And there appeared to him an angel of the Lord, standing on the right side of the altar of incense."}),"\n",(0,n.jsx)(h,{verse:12,children:"And Zachary seeing him, was troubled: and fear fell upon him."}),"\n",(0,n.jsx)(h,{verse:13,children:"But the angel said to him: Fear not, Zachary, for thy prayer is heard: and thy wife Elizabeth shall bear thee a son. And thou shalt call his name John."}),"\n",(0,n.jsx)(h,{verse:14,children:"And thou shalt have joy and gladness: and many shall rejoice in his nativity."}),"\n",(0,n.jsx)(h,{verse:15,children:"For he shall be great before the Lord and shall drink no wine nor strong drink: and he shall be filled with the Holy Ghost, even from his mother's womb."}),"\n",(0,n.jsx)(h,{verse:16,children:"And he shall convert many of the children of Israel to the Lord their God."}),"\n",(0,n.jsx)(h,{verse:17,children:"And he shall go before him in the spirit and power of Elias: that he may turn the hearts of the fathers unto the children and the incredulous to the wisdom of the just, to prepare unto the Lord a perfect people."}),"\n",(0,n.jsx)(h,{verse:18,children:"And Zachary said to the angel: Whereby shall I know this? For I am an old man, and my wife is advanced in years."}),"\n",(0,n.jsx)(h,{verse:19,children:"And the angel answering, said to him: I am Gabriel, who stand before God and am sent to speak to thee and to bring thee these good tidings."}),"\n",(0,n.jsx)(h,{verse:20,children:"And behold, thou shalt be dumb and shalt not be able to speak until the day wherein these things shall come to pass: because thou hast not believed my words, which shall be fulfilled in their time."}),"\n",(0,n.jsx)(h,{verse:21,children:"And the people were waiting for Zachary: and they wondered that he tarried so long in the temple."}),"\n",(0,n.jsx)(h,{verse:22,children:"And when he came out, he could not speak to them: and they understood that he had seen a vision in the temple. And he made signs to them and remained dumb."}),"\n",(0,n.jsx)(h,{verse:23,children:"And it came to pass, after the days of his office were accomplished, he departed to his own house."}),"\n",(0,n.jsx)(h,{verse:24,children:"And after those days, Elizabeth his wife conceived and hid herself five months, saying:"}),"\n",(0,n.jsx)(h,{verse:25,children:"Thus hath the Lord dealt with me in the days wherein he hath had regard to take away my reproach among men."}),"\n",(0,n.jsx)(h,{verse:26,children:"And in the sixth month, the angel Gabriel was sent from God into a city of Galilee, called Nazareth,"}),"\n",(0,n.jsx)(h,{verse:27,children:"To a virgin espoused to a man whose name was Joseph, of the house of David: and the virgin's name was Mary."}),"\n",(0,n.jsx)(h,{verse:28,children:"And the angel being come in, said unto her: Hail, full of grace, the Lord is with thee: blessed art thou among women."}),"\n",(0,n.jsx)(h,{verse:29,children:"Who having heard, was troubled at his saying and thought with herself what manner of salutation this should be."}),"\n",(0,n.jsx)(h,{verse:30,children:"And the angel said to her: Fear not, Mary, for thou hast found grace with God."}),"\n",(0,n.jsx)(h,{verse:31,children:"Behold thou shalt conceive in thy womb and shalt bring forth a son: and thou shalt call his name Jesus."}),"\n",(0,n.jsx)(h,{verse:32,children:"He shall be great and shall be called the Son of the Most High. And the Lord God shall give unto him the throne of David his father: and he shall reign in the house of Jacob for ever."}),"\n",(0,n.jsx)(h,{verse:33,children:"And of his kingdom there shall be no end."}),"\n",(0,n.jsx)(h,{verse:34,children:"And Mary said to the angel: How shall this be done, because I know not man?"}),"\n",(0,n.jsx)(h,{verse:35,children:"And the angel answering, said to her: The Holy Ghost shall come upon thee and the power of the Most High shall overshadow thee. And therefore also the Holy which shall be born of thee shall be called the Son of God."}),"\n",(0,n.jsx)(h,{verse:36,children:"And behold thy cousin Elizabeth, she also hath conceived a son in her old age: and this is the sixth month with her that is called barren."}),"\n",(0,n.jsx)(h,{verse:37,children:"Because no word shall be impossible with God."}),"\n",(0,n.jsx)(h,{verse:38,children:"And Mary said: Behold the handmaid of the Lord: be it done to me according to thy word. And the angel departed from her."}),"\n",(0,n.jsx)(h,{verse:39,children:"And Mary rising up in those days, went into the hill country with haste into a city of Juda."}),"\n",(0,n.jsx)(h,{verse:40,children:"And she entered into the house of Zachary and saluted Elizabeth."}),"\n",(0,n.jsx)(h,{verse:41,children:"And it came to pass that when Elizabeth heard the salutation of Mary, the infant leaped in her womb. And Elizabeth was filled with the Holy Ghost."}),"\n",(0,n.jsx)(h,{verse:42,children:"And she cried out with a loud voice and said: Blessed art thou among women and blessed is the fruit of thy womb."}),"\n",(0,n.jsx)(h,{verse:43,children:"And whence is this to me that the mother of my Lord should come to me?"}),"\n",(0,n.jsx)(h,{verse:44,children:"For behold as soon as the voice of thy salutation sounded in my ears, the infant in my womb leaped for joy."}),"\n",(0,n.jsx)(h,{verse:45,children:"And blessed art thou that hast believed, because those things shall be accomplished that were spoken to thee by the Lord."}),"\n",(0,n.jsx)(h,{verse:46,children:"And Mary said: My soul doth magnify the Lord."}),"\n",(0,n.jsx)(h,{verse:47,children:"And my spirit hath rejoiced in God my Saviour."}),"\n",(0,n.jsx)(h,{verse:48,children:"Because he hath regarded the humility of his handmaid: for behold from henceforth all generations shall call me blessed."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Shall call me blessed...These words are a prediction of that honour which the church in all ages should pay to the Blessed Virgin. Let Protestants examine whether they are any way concerned in this prophecy."})}),"\n",(0,n.jsx)(h,{verse:49,children:"Because he that is mighty hath done great things to me: and holy is his name."}),"\n",(0,n.jsx)(h,{verse:50,children:"And his mercy is from generation unto generations, to them that fear him."}),"\n",(0,n.jsx)(h,{verse:51,children:"He hath shewed might in his arm: he hath scattered the proud in the conceit of their heart."}),"\n",(0,n.jsx)(h,{verse:52,children:"He hath put down the mighty from their seat and hath exalted the humble."}),"\n",(0,n.jsx)(h,{verse:53,children:"He hath filled the hungry with good things: and the rich he hath sent empty away."}),"\n",(0,n.jsx)(h,{verse:54,children:"He hath received Israel his servant, being mindful of his mercy."}),"\n",(0,n.jsx)(h,{verse:55,children:"As he spoke to our fathers: to Abraham and to his seed for ever."}),"\n",(0,n.jsx)(h,{verse:56,children:"And Mary abode with her about three months. And she returned to her own house."}),"\n",(0,n.jsx)(h,{verse:57,children:"Now Elizabeth's full time of being delivered was come: and she brought forth a son."}),"\n",(0,n.jsx)(h,{verse:58,children:"And her neighbors and kinsfolks heard that the Lord had shewed his great mercy towards her: and they congratulated with her."}),"\n",(0,n.jsx)(h,{verse:59,children:"And it came to pass that on the eighth day they came to circumcise the child: and they called him by his father's name Zachary."}),"\n",(0,n.jsx)(h,{verse:60,children:"And his mother answering, said: Not so. But he shall be called John."}),"\n",(0,n.jsx)(h,{verse:61,children:"And they said to her: There is none of thy kindred that is called by this name."}),"\n",(0,n.jsx)(h,{verse:62,children:"And they made signs to his father, how he would have him called."}),"\n",(0,n.jsx)(h,{verse:63,children:"And demanding a writing table, he wrote, saying: John is his name. And they all wondered."}),"\n",(0,n.jsx)(h,{verse:64,children:"And immediately his mouth was opened and his tongue loosed: and he spoke, blessing God."}),"\n",(0,n.jsx)(h,{verse:65,children:"And fear came upon all their neighbours: and all these things were noised abroad over all the hill country of Judea."}),"\n",(0,n.jsx)(h,{verse:66,children:"And all they that had heard them laid them up in their heart, saying: What an one, think ye, shall this child be? For the hand of the Lord was with him."}),"\n",(0,n.jsx)(h,{verse:67,children:"And Zachary his father was filled with the Holy Ghost. And he prophesied, saying:"}),"\n",(0,n.jsx)(h,{verse:68,children:"Blessed be the Lord God of Israel: because he hath visited and wrought the redemption of his people."}),"\n",(0,n.jsx)(h,{verse:69,children:"And hath raised up an horn of salvation to us, in the house of David his servant."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Horn of salvation...That is, A powerful salvation, as Dr. Witham translates it. For in the Scripture, by horn is generally understood strength and power."})}),"\n",(0,n.jsx)(h,{verse:70,children:"As he spoke by the mouth of his holy prophets, who are from the beginning."}),"\n",(0,n.jsx)(h,{verse:71,children:"Salvation from our enemies and from the hand of all that hate us."}),"\n",(0,n.jsx)(h,{verse:72,children:"To perform mercy to our fathers and to remember his holy testament."}),"\n",(0,n.jsx)(h,{verse:73,children:"The oath, which he swore to Abraham our father, that he would grant to us."}),"\n",(0,n.jsx)(h,{verse:74,children:"That being delivered from the hand of our enemies, we may serve him without fear:"}),"\n",(0,n.jsx)(h,{verse:75,children:"In holiness and justice before him, all our days."}),"\n",(0,n.jsx)(h,{verse:76,children:"And thou, child, shalt be called the prophet of the Highest: for thou shalt, go before the face of the Lord to prepare his ways:"}),"\n",(0,n.jsx)(h,{verse:77,children:"To give knowledge of salvation to his people, unto the remission of their sins."}),"\n",(0,n.jsx)(h,{verse:78,children:"Through the bowels of the mercy of our God, in which the Orient from on high hath visited us:"}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: The Orient...It is one of the titles of the Messias, the true light of the world, and the sun of justice."})}),"\n",(0,n.jsx)(h,{verse:79,children:"To enlighten them that sit in darkness and in the shadow of death: to direct our feet into the way of peace."}),"\n",(0,n.jsx)(h,{verse:80,children:"And the child grew and was strengthened in spirit: and was in the deserts until the day of his manifestation to Israel."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>i,x:()=>a});var n=h(14041);const s={},o=n.createContext(s);function i(e){const t=n.useContext(o);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),n.createElement(o.Provider,{value:t},e.children)}}}]);